#include "../perlin-cuda/noise.cu"
#include "study_params.h"
#include <fstream>
#include <cstdio>
#include <chrono>
#include <algorithm>
static void ck(cudaError_t e){if(e!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(e));}
struct G {uint8_t*p;size_t n;G(size_t bytes,uint8_t init):n(bytes){std::vector<uint8_t>a(n+2*PG,173);std::fill(a.begin()+PG,a.begin()+PG+n,init);ck(cudaMalloc(&p,a.size()));if(uintptr_t(p+PG)%256)throw std::runtime_error("output alignment");ck(cudaMemcpy(p,a.data(),a.size(),cudaMemcpyHostToDevice));}~G(){cudaFree(p);}std::vector<uint8_t>read(){std::vector<uint8_t>a(n+2*PG);ck(cudaMemcpy(a.data(),p,a.size(),cudaMemcpyDeviceToHost));return a;}};
__global__ void echo_parameters(uint8_t*out,NoiseParams p,int height,int ns){if(threadIdx.x==0){const uint8_t*a=reinterpret_cast<const uint8_t*>(&p);for(int j=0;j<20;j++)out[j]=a[j];int v[]={int(WIN_WIDTH),height,ns,height/ns};const uint8_t*b=reinterpret_cast<const uint8_t*>(v);for(int j=0;j<16;j++)out[20+j]=b[j];}}
static std::vector<uint8_t>actual_constants(){std::vector<uint8_t>a(1088);ck(cudaMemcpyFromSymbol(a.data(),_hash,1024));ck(cudaMemcpyFromSymbol(a.data()+1024,gradientX,32));ck(cudaMemcpyFromSymbol(a.data()+1056,gradientY,32));return a;}
static void append(std::vector<uint8_t>&a,const std::vector<uint8_t>&b){a.insert(a.end(),b.begin(),b.end());}
static double execute(int trial){std::vector<uint8_t>prefix,outputs;if(trial){prefix.reserve(PREFIX);outputs.reserve(PREFIX);}double seconds=0;for(int c=0;c<8;c++){auto z=CASES[c];NoiseParams params{z.ppu,z.seed,z.octaves,z.lac,z.persistence};uint64_t bytes=pixels(c)*4;G out(bytes,17),param(36,0);std::vector<cudaStream_t>streams(z.streams);for(auto&s:streams)ck(cudaStreamCreate(&s));echo_parameters<<<1,32>>>(param.p+PG,params,z.height,z.streams);ck(cudaDeviceSynchronize());if(trial){append(prefix,actual_constants());append(prefix,param.read());append(prefix,out.read());}int ph=z.height/z.streams;dim3 threads(16,16),blocks((PW+15)/16,(ph+15)/16);ck(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int i=0;i<z.streams;i++)perlin<<<blocks,threads,0,streams[i]>>>(ph*i,ph,params,out.p+PG);ck(cudaDeviceSynchronize());seconds+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();if(trial){append(outputs,actual_constants());append(outputs,param.read());append(outputs,out.read());}for(auto&s:streams)ck(cudaStreamDestroy(s));}
if(trial){if(prefix.size()!=PREFIX||outputs.size()!=PREFIX)throw std::runtime_error("artifact count");std::string name="perlin_trial"+std::to_string(trial)+".bin";std::ofstream f(name,std::ios::binary);f.write(reinterpret_cast<const char*>(prefix.data()),prefix.size());f.write(reinterpret_cast<const char*>(outputs.data()),outputs.size());f.close();if(!f)throw std::runtime_error("artifact write");double ae=0,re=0;if(!perlin_check(name.c_str(),&ae,&re))throw std::runtime_error("independent full saved-field audit");printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":true,\"checked_values\":%llu,\"max_abs_error\":%.12g,\"max_rel_error\":%.12g,\"jit_excluded\":true,\"timing_region\":\"sum8_named_perlin_source16x16_multistream_launch_wholecontextcompletion\",\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint8\",\"count\":%llu,\"byte_order\":\"little\"}}\n",trial,seconds,(unsigned long long)ARTIFACT,ae,re,name.c_str(),(unsigned long long)ARTIFACT);fflush(stdout);}return seconds;}
int main(){try{printf("PERLIN_STUDY_BEGIN originalwidth61440 namedstrips512_16_48; one-level quantization contract\n");fflush(stdout);execute(0);for(int trial=1;trial<=5;trial++)execute(trial);}catch(const std::exception&e){fprintf(stderr,"%s\n",e.what());return 1;}}
